function extractTopicRecords(html) {
 const blocks = [...html.matchAll(/self\.__next_f\.push\((\[[\s\S]*?\])\)<\/script>/g)];
 const text = blocks.map(m => { try { return JSON.parse(m[1]); } catch { return []; } })
  .filter(a => a[0] === 1 && typeof a[1] === 'string').map(a => a[1]).join('');
 const rows = [];
 for (const line of text.split('\n')) {
  const p = line.indexOf(':'); if (p < 1) continue;
  try { const v = JSON.parse(line.slice(p+1)); const props = Array.isArray(v) ? v[3] : null;
   if (props && Array.isArray(props.data)) rows.push(...props.data.filter(x => x && x.slug && x.publishedAt));
  } catch {}
 }
 return [...new Map(rows.map(x=>[x.id,x])).values()];
}
// 不可eval。公開HTML內嵌資料不是有穩定性承諾的API；欄位不存在要停止覆寫並保留舊資料。
